<template>
  <section class="behavior-analysis" aria-labelledby="behavior-analysis-title">
    <header class="analysis-header"><div><span>从人物选择到实际结算</span><h3 id="behavior-analysis-title">行为、六维与交手解析</h3></div></header>
    <div class="analysis-tabs" role="group" aria-label="解析内容">
      <button v-for="item in tabs" :key="item.id" type="button" :aria-pressed="tab===item.id" @click="tab=item.id">{{item.label}}</button>
    </div>

    <div v-if="tab==='behavior'" class="analysis-panel" data-analysis-panel="behavior">
      <ol v-if="analysis.process?.length" class="analysis-process"><li v-for="(step,index) in analysis.process" :key="index"><span>{{String(index+1).padStart(2,'0')}}</span><div><h4>{{step.title}}</h4><p>{{step.detail}}</p></div></li></ol>
      <div class="behavior-cards">
        <article v-for="person in analysis.behaviors||[]" :key="person.id" class="behavior-card">
          <h4>{{person.name}}</h4>
          <dl><template v-for="field in behaviorFields" :key="field.key"><dt>{{field.label}}</dt><dd>{{person[field.key]||'—'}}</dd></template></dl>
        </article>
      </div>
      <div v-if="analysis.consequences?.length" class="analysis-consequences"><article v-for="(item,index) in analysis.consequences" :key="index"><h4>{{item.title}}</h4><p>{{item.detail}}</p></article></div>
    </div>

    <div v-else-if="tab==='dimensions'" class="analysis-panel" data-analysis-panel="dimensions">
      <div class="dimension-cards"><article v-for="dimension in analysis.dimensions||[]" :key="dimension.key"><h4><span>{{dimension.label}}</span>{{dimension.meaning}}</h4><dl><dt>故事中怎样体现</dt><dd>{{dimension.sceneUse}}</dd><dt>交手中怎样起作用</dt><dd>{{dimension.combatUse}}</dd><dt>作用边界</dt><dd>{{dimension.boundary}}</dd></dl></article></div>
      <section v-if="selectedProfile" class="profile-formula" aria-label="人物六维实际值">
        <div class="analysis-subhead"><h4>人物数值 · 基础到实际</h4><label>选择人物 <select :value="selectedProfile.id" @change="profileId=$event.target.value"><option v-for="person in analysis.profiles||[]" :key="person.id" :value="person.id">{{person.name}}</option></select></label></div>
        <p class="analysis-note">以下数值与公式来自本次服务端演算，展开任一属性可查看完整代入过程。</p>
        <div class="stats-table-wrap"><table class="stats-table"><caption>{{selectedProfile.name}}的六维</caption><thead><tr><th scope="col">维度</th><th scope="col">基础值</th><th scope="col">实际值</th><th scope="col">用途</th></tr></thead><tbody><tr v-for="stat in selectedProfile.formulaBook?.stats||[]" :key="stat.key"><th scope="row">{{stat.label}}</th><td>{{number(stat.base)}}</td><td><strong>{{number(stat.actual)}}</strong></td><td>{{stat.description}}</td></tr></tbody></table></div>
        <div :key="selectedProfile.id" class="formula-details">
          <details v-for="stat in selectedProfile.formulaBook?.stats||[]" :key="stat.key"><summary>{{stat.label}}的公式代入 <span>{{number(stat.base)}} → {{number(stat.actual)}}</span></summary><div class="formula-detail-body"><p class="formula-code">{{stat.formula}}</p><dl><dt>成长曲线 C(基础)</dt><dd>{{number(stat.growthValue)}}</dd><dt>根基乘数</dt><dd>{{number(stat.masteryMultiplier)}}</dd><dt>辅助属性</dt><dd><span v-for="(name,index) in stat.supportNames||[]" :key="index">{{name}} {{number(stat.supportBases?.[index])}}{{index<(stat.supportNames?.length||0)-1?' · ':''}}</span></dd><dt>协同 S</dt><dd>{{number(stat.synergy)}}</dd><dt>协同乘数</dt><dd>{{number(stat.synergyMultiplier)}}</dd><dt>四舍五入前</dt><dd>{{number(stat.unrounded)}}</dd><dt>最终实际值</dt><dd>{{number(stat.actual)}}</dd></dl></div></details>
        </div>
        <details v-if="selectedProfile.formulaBook?.common?.length" class="common-formula"><summary>通用成长与协同公式</summary><ul><li v-for="(line,index) in selectedProfile.formulaBook.common" :key="index">{{line}}</li></ul></details>
      </section>
    </div>

    <div v-else class="analysis-panel" data-analysis-panel="combat">
      <p class="analysis-note combat-example-notice">以下为讲解对照，不是当前故事已发生的战斗。切换案例只查看演算，不会让人物交手或修改存档。</p>
      <section v-if="analysis.combatRule" class="combat-rule" aria-label="交手胜负规则"><h4>差值与阈值如何决定胜负</h4><dl><dt>攻守差值 D</dt><dd>{{analysis.combatRule.difference}}</dd><dt>胜负阈值 T</dt><dd>{{analysis.combatRule.threshold}}</dd><dt>胜负条件</dt><dd>{{analysis.combatRule.decision}}</dd></dl></section>
      <div v-if="selectedCase" :key="selectedCase.id" class="combat-case">
        <div class="analysis-subhead"><h4>对照交手推演</h4><label>选择案例 <select aria-label="选择交手案例" :value="selectedCase.id" @change="caseId=$event.target.value"><option v-for="item in analysis.combatCases||[]" :key="item.id" :value="item.id">{{item.title}}</option></select></label></div>
        <h4 class="combat-title">{{selectedCase.title}}</h4><p class="combat-context">{{selectedCase.context}}</p>
        <div class="combat-fighters"><article v-for="fighter in combatFighters" :key="fighter.side" class="combat-fighter"><h4><small>{{fighter.side}}</small>{{fighter.name}}</h4><div class="stats-table-wrap"><table class="stats-table"><caption>{{fighter.name}} · 基础与实际六维</caption><thead><tr><th scope="col">维度</th><th scope="col">基础值</th><th scope="col">实际值</th></tr></thead><tbody><tr v-for="stat in fighter.formulaBook?.stats||[]" :key="stat.key"><th scope="row">{{stat.label}}</th><td>{{number(stat.base)}}</td><td>{{number(stat.actual)}}</td></tr></tbody></table></div><details v-if="douOf(fighter)" class="combat-dou-formula"><summary>实际斗的公式代入</summary><div class="formula-detail-body"><p class="formula-code">{{douOf(fighter).formula}}</p><p class="formula-substitution">{{number(douOf(fighter).growthValue)}} × {{number(douOf(fighter).masteryMultiplier)}} × {{number(douOf(fighter).synergyMultiplier)}} → {{number(douOf(fighter).unrounded)}} → {{number(douOf(fighter).actual)}}</p><p class="analysis-note">依次为成长值、根基乘数、协同乘数、未取整值与最终实际值。</p></div></details></article></div>
        <dl v-if="selectedCase.comparison" class="combat-comparison"><div><dt>攻方实际斗</dt><dd>{{number(selectedCase.comparison.actorActualDou)}}</dd></div><div><dt>守方实际斗</dt><dd>{{number(selectedCase.comparison.targetActualDou)}}</dd></div><div><dt>攻守差值</dt><dd>{{number(selectedCase.comparison.difference)}}</dd></div><div><dt>胜负阈值 T</dt><dd>{{number(selectedCase.comparison.threshold)}}</dd></div><div><dt>结算结果</dt><dd>{{selectedCase.comparison.outcomeLabel}}</dd></div></dl>
        <div v-if="selectedCase.comparison?.differenceFormula||selectedCase.comparison?.thresholdFormula" class="combat-substitution" aria-label="本案例公式代入"><h4>本案例的数值代入</h4><p v-if="selectedCase.comparison.differenceFormula">{{selectedCase.comparison.differenceFormula}}</p><p v-if="selectedCase.comparison.thresholdFormula">{{selectedCase.comparison.thresholdFormula}}</p></div>
        <p class="combat-interpretation">{{selectedCase.interpretation}}</p>
        <h4 v-if="selectedCase.statDeltas?.length" class="combat-delta-title">实际交手并保存后才生效的基础六维变化</h4>
        <ul v-if="selectedCase.statDeltas?.length" class="combat-deltas"><li v-for="(person,index) in selectedCase.statDeltas" :key="index"><strong>{{person.name}}</strong><span v-for="change in changesOf(person.changes)" :key="change.key">{{change.label}} {{signed(change.value)}}</span></li></ul>
      </div>
      <p v-else class="analysis-note">本次没有交手案例。</p>
      <section v-if="analysis.consequences?.length" class="analysis-consequences combat-consequences" aria-label="交手后果与处置"><article v-for="(item,index) in analysis.consequences" :key="index"><h4>{{item.title}}</h4><p>{{item.detail}}</p></article></section>
    </div>
    <aside v-if="analysis.boundaries?.length" class="analysis-boundaries" aria-label="规则作用边界"><h4>作用边界</h4><ul><li v-for="(line,index) in analysis.boundaries" :key="index">{{line}}</li></ul></aside>
  </section>
</template>

<script setup>
import {ref,computed} from 'vue'
const props=defineProps({analysis:{type:Object,required:true}})
const tab=ref('behavior'),profileId=ref(''),caseId=ref('')
const tabs=[{id:'behavior',label:'行为设计'},{id:'dimensions',label:'六维实际应用'},{id:'combat',label:'战斗逻辑'}]
const behaviorFields=[{key:'goal',label:'想得到什么'},{key:'known',label:'已知与误判'},{key:'choice',label:'为什么这样行动'},{key:'risk',label:'承担的风险'},{key:'consequence',label:'产生的后果'},{key:'alternative',label:'还能怎样选择'}]
const statLabels={zhi:'知',hui:'慧',dou:'斗',wen:'闻',ben:'本',gui:'归'}
const selectedProfile=computed(()=>props.analysis.profiles?.find(person=>person.id===profileId.value)||props.analysis.profiles?.[0])
const selectedCase=computed(()=>props.analysis.combatCases?.find(item=>item.id===caseId.value)||props.analysis.combatCases?.[0])
const combatFighters=computed(()=>selectedCase.value?[{...selectedCase.value.attacker,side:'攻方'},{...selectedCase.value.defender,side:'守方'}]:[])
function number(value){if(value==null||value==='')return '—';const n=Number(value);return Number.isFinite(n)?n.toLocaleString('zh-CN',{maximumFractionDigits:4,useGrouping:false}):String(value)}
function signed(value){return Number(value)>0?'+'+number(value):number(value)}
function douOf(person){return person.formulaBook?.stats?.find(stat=>String(stat.key).toLowerCase()==='dou')}
function changesOf(changes){return Object.entries(changes||{}).filter(([,value])=>Number(value)).map(([key,value])=>({key,value,label:statLabels[key]||key}))}
</script>

