.combat-title{font-weight:500;letter-spacing:1px;font-size:17px;margin:22px 0 9px}.combat-context,.combat-interpretation{font-size:13px;line-height:2;color:#718994;margin:0 0 18px}.combat-fighters{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:19px}.combat-fighter{padding:17px;border:1px solid #cbd8db;min-width:0}.combat-fighter>h4{font-weight:500;font-size:18px;letter-spacing:2px;margin:0 0 17px}.combat-fighter>h4 small{font-size:10px;color:#8b9fa9;margin-right:11px}.combat-fighter .stats-table th,.combat-fighter .stats-table td{padding:8px 11px}.formula-substitution{font:12px/2 ui-monospace,monospace;color:#56798e;overflow-wrap:anywhere}.combat-comparison{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px;padding:17px 0;border-bottom:1px solid #cad8dc;margin:15px 0}.combat-comparison dt{font-size:10px;color:#8b9eaa;line-height:1.9}.combat-comparison dd{font:22px/1.5 Georgia,serif;color:#4e778c;margin:8px 0 0}.combat-comparison>div:last-child dd{font-family:inherit;font-size:14px;line-height:1.9;letter-spacing:1px}.combat-deltas{padding:0;list-style:none;font-size:12px;margin:15px 0}.combat-deltas li{display:flex;gap:18px;line-height:2.1;flex-wrap:wrap;margin:6px 0;color:#839ca7}.combat-deltas strong{font-weight:500;color:#5f8191;min-width:55px}
